import{_ as t,o as e,c as r,af as a}from"./chunks/framework.Dt3O48XQ.js";const g=JSON.parse('{"title":"房间机制（概览）","description":"","frontmatter":{},"headers":[],"relativePath":"rooms/overview.md","filePath":"rooms/overview.md","lastUpdated":null}'),d={name:"rooms/overview.md"};function c(s,o,i,h,m,n){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="房间机制-概览" tabindex="-1">房间机制（概览） <a class="header-anchor" href="#房间机制-概览" aria-label="Permalink to &quot;房间机制（概览）&quot;">​</a></h1><p>在 <code>xymj-colyseus-server</code> 里，<strong>Colyseus 房间（Room）</strong> 是实时对战、匹配大厅、聊天频道等业务的核心载体：客户端通过 <strong>WebSocket</strong> 与某个 <strong>房间名（<code>roomName</code>）</strong> 下的服务端逻辑进程通信，而不是每个 HTTP 请求单独短连接。</p><h2 id="房间在整体架构中的位置" tabindex="-1">房间在整体架构中的位置 <a class="header-anchor" href="#房间在整体架构中的位置" aria-label="Permalink to &quot;房间在整体架构中的位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>HTTP API</th><th>Colyseus 房间</th></tr></thead><tbody><tr><td>连接方式</td><td>请求 / 响应，用完即结束</td><td><strong>长连接</strong>，可长时间保持</td></tr><tr><td>典型用途</td><td>登录注册、支付、配置拉取</td><td>对局状态、匹配排队、频道聊天、帧同步输入</td></tr><tr><td>鉴权</td><td><code>Authorization: Bearer</code> 等</td><td>进房时在 <strong><code>joinOrCreate</code> / <code>joinById</code> 的 options</strong> 里带 JWT（约定见 <a href="/xcs.github.io/guide/jwt-room-auth.html">JWT 与房间鉴权</a>）</td></tr></tbody></table><p>常见流程：<strong>REST 登录拿到 token → 客户端再连 Colyseus 并进房</strong>。同一用户可同时存在于多个房间（例如一边在 <strong><code>matchmaker_room</code></strong> 排队，另一边已进入 <strong><code>chat_team_room</code></strong>），只要你方客户端发起多次 join。</p><h2 id="本仓库注册的房间类型-客户端-roomname" tabindex="-1">本仓库注册的房间类型（客户端 <code>roomName</code>） <a class="header-anchor" href="#本仓库注册的房间类型-客户端-roomname" aria-label="Permalink to &quot;本仓库注册的房间类型（客户端 `roomName`）&quot;">​</a></h2><p>与 <code>src/app.config.ts</code> 中注册一致（详见 <a href="/xcs.github.io/guide/project-structure.html">项目结构</a>）：</p><table tabindex="0"><thead><tr><th>房间名</th><th>服务端类（示意）</th><th>典型用途</th><th>备注</th></tr></thead><tbody><tr><td><code>my_room</code></td><td><code>MyRoom</code></td><td>示例 / 模板</td><td>熟悉 Schema、消息注册</td></tr><tr><td><code>matchmaker_room</code></td><td><code>MatchmakerRoom</code></td><td>主动匹配、Party 房间码</td><td><strong>依赖 Redis</strong>（队列、跨进程通知）</td></tr><tr><td><code>game_room</code></td><td><code>GameRoomExample</code>（示例实现）</td><td>帧同步对局</td><td>多由匹配下发 <code>joinById</code>；含 <code>input</code>、重连；正式项目宜 fork 自有房间类</td></tr><tr><td><code>chat_world_room</code> 等</td><td><code>WorldChatRoom</code> 等</td><td>世界 / 工会 / 附近 / 队伍聊天</td><td>世界频道常配合 <strong>Redis</strong> 跨实例同步</td></tr><tr><td><code>loadtest_room</code></td><td><code>LoadTestRoom</code></td><td>压连接 / 吞吐</td><td><strong>无 JWT</strong>，仅测试；生产建议关闭</td></tr></tbody></table><p>同一玩法不要混用房间名：例如「路人匹配」与「好友房」共用协议层消息（如 <code>match:find</code>）但仍在 <strong><code>matchmaker_room</code></strong> 内完成；真正对战在进入 <strong><code>game_room</code></strong> 后才开始。</p><h2 id="两种同步手段-schema-状态-vs-自定义消息" tabindex="-1">两种同步手段：Schema 状态 vs 自定义消息 <a class="header-anchor" href="#两种同步手段-schema-状态-vs-自定义消息" aria-label="Permalink to &quot;两种同步手段：Schema 状态 vs 自定义消息&quot;">​</a></h2><ul><li><strong>Schema 状态（<code>@colyseus/schema</code>）</strong>：房间内有 <strong><code>Room.state</code></strong>，服务端修改字段后 Colyseus <strong>自动增量同步</strong>给所有订阅客户端，适合「盘面数据」「血量字典」等结构化状态。详见 <a href="/xcs.github.io/rooms/state.html">状态同步（Schema）</a>。</li><li><strong><code>room.send</code> / <code>onMessage</code></strong>：适合一次性事件、指令响应、聊天文本等；不必进入 Schema。约定集中写在 <a href="/xcs.github.io/reference/protocol.html">消息协议</a>，专题见 <a href="/xcs.github.io/rooms/messages.html">多模式聊天</a>、<a href="/xcs.github.io/rooms/matchmaking.html">匹配与开房</a>。</li></ul><p>很多房间 <strong>两者并用</strong>：例如 <code>game_room</code> 用 Schema 保存帧相关状态，用消息下发 <code>frameSync</code>、<code>playerOffline</code> 等事件。</p><h2 id="何时拆成多个房间" tabindex="-1">何时拆成多个房间 <a class="header-anchor" href="#何时拆成多个房间" aria-label="Permalink to &quot;何时拆成多个房间&quot;">​</a></h2><ul><li><strong>按玩法隔离</strong>：匹配 / 大厅（<code>matchmaker_room</code>）与单局对战（<code>game_room</code>）分离，避免大厅广播冲击对局逻辑。</li><li><strong>按频道隔离</strong>：世界 / 工会 / 附近 / 队伍使用不同 <code>chat_*_room</code>，进房 options（<code>guildId</code>、<code>teamId</code>、坐标）决定谁能收到聊天。</li><li><strong>按人数与生命周期</strong>：一局结束可销毁 <code>game_room</code> 实例；聊天房可按业务常驻或短 TTL。</li></ul><h2 id="环境与依赖-与房间相关" tabindex="-1">环境与依赖（与房间相关） <a class="header-anchor" href="#环境与依赖-与房间相关" aria-label="Permalink to &quot;环境与依赖（与房间相关）&quot;">​</a></h2><ul><li><strong>Redis</strong>：匹配队列、部分聊天跨进程、<code>match:found</code> 投递、会话与重连键等多处使用；本地跑 <strong>Matchmaking / 多实例</strong> 前请先启动 Redis（见 <a href="/xcs.github.io/guide/configuration.html">配置说明</a>）。</li><li><strong>MySQL / TypeORM</strong>：偏 HTTP 与持久化业务；房间内存状态仍以 Colyseus 房间与 Redis 为主。</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li><a href="/xcs.github.io/rooms/lifecycle.html">生命周期</a> — 回调顺序、客户端与服务端视角</li><li><a href="/xcs.github.io/rooms/auth.html">鉴权与权限</a>（细则：<a href="/xcs.github.io/guide/jwt-room-auth.html">JWT 与房间鉴权</a>）</li><li><a href="/xcs.github.io/rooms/state.html">状态同步（Schema）</a></li><li><a href="/xcs.github.io/rooms/messages.html">多模式聊天</a></li><li><a href="/xcs.github.io/rooms/matchmaking.html">匹配与开房</a>（<code>matchmaker_room</code> + Redis / 房间码）</li><li><a href="/xcs.github.io/rooms/frame-sync-game-room.html">帧同步与游戏房</a>（<code>game_room</code>、<code>input</code>、重连）</li></ol><p>更多按玩法选型可先看 <a href="/xcs.github.io/scenarios/overview.html">应用场景概览</a>。</p>',19)])])}const u=t(d,[["render",c]]);export{g as __pageData,u as default};
